Object.assign(SNIP,{"h22lis": "vector<long long> duoi;\nfor (long long x : a) {\n    auto it = lower_bound(duoi.begin(), duoi.end(), x);\n    if (it == duoi.end()) duoi.push_back(x);\n    else *it = x;\n}\ncout << duoi.size() << \"\\n\";", "h22tui": "vector<long long> dp(W + 1, 0);\nfor (int i = 0; i < n; i++)\n    for (int w = W; w >= kl[i]; w--)          // từ lớn xuống nhỏ\n        dp[w] = max(dp[w], dp[w - kl[i]] + gt[i]);\ncout << dp[W] << \"\\n\";"});PRESET_NOTES["l22"]={"Ví dụ: LIS O(n²)": "dp = 1 1 2 1 3 4 2 4: ví dụ 1, 4, 5, 9 hoặc 3, 4, 5, 6 dài 4.", "Ví dụ: LIS bằng lower_bound": "Mảng duoi cuối cùng là 1 2 5 6 — không phải một dãy con thật, nhưng độ dài 4 là đáp án đúng.", "Ví dụ: Cái túi 0/1": "Tối ưu lấy đồ vật khối lượng 3 và 4: giá trị 9. Vòng w đi ngược nên mỗi đồ vật dùng tối đa một lần."};EX_HINTS["l22"]=[["Code mẫu đúng nhưng O(n²): quá chậm với n = 10⁵.", "Mảng duoi luôn tăng: dùng lower_bound tìm vị trí đầu tiên ≥ x.", "Tăng ngặt nên lower_bound; nếu cho phép bằng nhau thì upper_bound."], ["Code mẫu duyệt w tăng dần: một đồ vật bị lấy nhiều lần (thử 3 đồ vật khối lượng 2, W = 5).", "Đổi chiều vòng w: từ W xuống kl[i].", "Tổng giá trị tới 10¹¹: long long."], ["Code mẫu thử mọi tập con: 2ⁿ, và chỉ xét được 20 tờ đầu.", "Cái túi với giá trị đúng / sai: dp[s] = có tạo được tổng s.", "Mỗi tờ dùng một lần: duyệt s từ S xuống x."]];
