const PR22=[{label:"Ví dụ: LIS O(n²)",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};\n    int n = a.size(), tot = 0;\n    vector<int> dp(n, 1);\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < i; j++)\n            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);\n        tot = max(tot, dp[i]);\n    }\n    cout << tot << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i","j"]},{type:"cells",of:"dp",ptr:["i"]}]},{label:"Ví dụ: LIS bằng lower_bound",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};\n    vector<int> duoi;\n    for (int x : a) {\n        auto it = lower_bound(duoi.begin(), duoi.end(), x);\n        if (it == duoi.end()) duoi.push_back(x);   // nối dài\n        else *it = x;                  // thay để đuôi nhỏ hơn\n    }\n    cout << duoi.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"duoi"},{type:"vars",names:["x"]}]},{label:"Ví dụ: Cái túi 0/1",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> kl = {1, 3, 4, 5}, gt = {1, 4, 5, 7};\n    int n = kl.size(), W = 7;\n    vector<int> dp(W + 1, 0);\n    for (int i = 0; i < n; i++)\n        for (int w = W; w >= kl[i]; w--)\n            dp[w] = max(dp[w], dp[w - kl[i]] + gt[i]);\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"dp",ptr:["w"]},{type:"vars",names:["i"]}]}];
