makeEx2(document.getElementById("ex-l22"),sim22,[{t:"Tăng trưởng dài nhất",d:"File TANGTRUONG.INP: dòng 1 là n (1 ≤ n ≤ 10⁵); dòng 2 là n số nguyên (|aᵢ| ≤ 10⁹): doanh thu n tháng. Chọn ra một số tháng (giữ thứ tự) có doanh thu tăng ngặt. Ghi vào TANGTRUONG.OUT số tháng nhiều nhất chọn được.",tests:[{in:"8\n3 1 4 1 5 9 2 6",out:"4"},{in:"1\n5",out:"1"},{in:"3\n5 5 5",out:"1"},{in:"4\n4 3 2 1",out:"1"},{in:"4\n1 2 3 4",out:"4"},{in:"50\n948548100 -698560737 -478983831 -949284718 316594021 -39788237 -604318314 507434550 -741030513 588264534 398916457 886833683 -257733366 702045651 910296108 -828936917 -502338939 -421755925 -893353125 -313982401 290943240 -615309564 185407232 471585436 574381231 983950977 -76558411 520665330 897484781 -895975169 239408069 892722061 -954218750 266061483 -433123375 -332817197 -94795669 -591692885 -612312369 824949814 -760410112 251604772 139975588 565268099 662049555 216147732 -868634335 499771030 -298988817 314957114",out:"10"},{in:"60\n5 4 2 6 4 10 8 2 4 4 10 2 6 0 5 8 0 6 4 8 4 8 6 6 10 2 4 9 5 6 9 0 4 9 9 8 8 8 6 10 8 6 1 1 7 5 1 6 6 0 3 8 3 6 0 1 7 3 2 0",out:"7"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"TANGTRUONG.INP\", \"r\")) {\n        freopen(\"TANGTRUONG.INP\", \"r\", stdin);\n        freopen(\"TANGTRUONG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    vector<int> dp(n, 1);\n    int tot = 0;\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < i; j++)\n            if (a[j] < a[i]) dp[i] = max(dp[i], dp[j] + 1);\n        tot = max(tot, dp[i]);\n    }\n    cout << tot << \"\\n\";\n    return 0;\n}",file:"TANGTRUONG",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100003).join(" "),ns:[200,800,3200],need:"nlogn",limit:n=>80*n*Math.log2(n)+500,why:"dp O(n²) quá chậm; mảng đuôi với lower_bound là O(n log n)."}},{t:"Ba lô",d:"File BALO.INP: dòng 1 là n, W (1 ≤ n ≤ 100, 1 ≤ W ≤ 10⁵); n dòng sau mỗi dòng khối lượng kᵢ (1 ≤ kᵢ ≤ W) và giá trị vᵢ (1 ≤ vᵢ ≤ 10⁹) của một đồ vật. Mỗi đồ vật lấy tối đa một lần. Ghi vào BALO.OUT tổng giá trị lớn nhất với tổng khối lượng không quá W.",tests:[{in:"4 7\n1 1\n3 4\n4 5\n5 7",out:"9"},{in:"1 4\n5 10",out:"0"},{in:"3 5\n2 3\n2 3\n2 3",out:"6"},{in:"1 1\n1 1000000000",out:"1000000000"},{in:"10 50\n18 67450897\n13 574937748\n12 144518915\n6 854598939\n11 836275298\n12 694794291\n21 793540725\n7 216367003\n15 703921282\n2 744805249",out:"3834395059"},{in:"20 200\n13 780883037\n7 70720874\n25 690703456\n53 766744269\n16 379861163\n19 842000879\n76 118943631\n59 880248387\n6 867276254\n16 653272949\n64 277970144\n91 128292742\n68 19530794\n18 200608297\n75 536880030\n37 376076482\n88 681371678\n96 68772432\n61 365688327\n61 104422050",out:"5551850105"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"BALO.INP\", \"r\")) {\n        freopen(\"BALO.INP\", \"r\", stdin);\n        freopen(\"BALO.OUT\", \"w\", stdout);\n    }\n    int n, W;\n    cin >> n >> W;\n    vector<int> kl(n);\n    vector<long long> gt(n);\n    for (int i = 0; i < n; i++) cin >> kl[i] >> gt[i];\n    vector<long long> dp(W + 1, 0);\n    for (int i = 0; i < n; i++)\n        for (int w = kl[i]; w <= W; w++)       // từ nhỏ lên lớn\n            dp[w] = max(dp[w], dp[w - kl[i]] + gt[i]);\n    cout << dp[W] << \"\\n\";\n    return 0;\n}",file:"BALO"},{t:"Đủ tiền",d:"File DUTIEN.INP: dòng 1 là n, S (1 ≤ n ≤ 100, 1 ≤ S ≤ 10⁵); dòng 2 là n số nguyên dương (≤ 10⁵): mệnh giá n tờ tiền trong ví (mỗi tờ dùng một lần). Ghi vào DUTIEN.OUT YES nếu chọn được một số tờ có tổng đúng bằng S, ngược lại NO.",tests:[{in:"6 9\n3 34 4 12 5 2",out:"YES"},{in:"6 30\n3 34 4 12 5 2",out:"NO"},{in:"1 5\n5",out:"YES"},{in:"1 3\n5",out:"NO"},{in:"50 99\n2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2 2",out:"NO"},{in:"30 777\n22 81 89 77 56 90 35 23 6 10 25 46 87 16 28 69 33 63 9 24 3 36 97 13 75 61 80 27 52 45",out:"YES"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DUTIEN.INP\", \"r\")) {\n        freopen(\"DUTIEN.INP\", \"r\", stdin);\n        freopen(\"DUTIEN.OUT\", \"w\", stdout);\n    }\n    int n, S;\n    cin >> n >> S;\n    vector<int> a(n);\n    for (auto& x : a) cin >> x;\n    bool ok = false;\n    for (int mask = 0; mask < (1 << min(n, 20)); mask++) {   // thử mọi tập con (chỉ 20 tờ đầu)\n        long long t = 0;\n        for (int i = 0; i < min(n, 20); i++) if (mask >> i & 1) t += a[i];\n        if (t == S) ok = true;\n    }\n    cout << (ok ? \"YES\" : \"NO\") << \"\\n\";\n    return 0;\n}",file:"DUTIEN",perf:{gen:n=>"20 "+(n*2)+"\n"+Array.from({length:20},(_,i)=>2*(i+3)).join(" "),ns:[200,800,3200],need:"n",limit:n=>200*n+5000,why:"Thử mọi tập con là O(2ⁿ · n). Quy hoạch động O(n · S)."}}]);

